-- ============================================
-- Finance Profile Schema for Apache Derby
-- 金融機関(リテールバンキング)システム - テーブル定義
--
-- 命名規約は manufacturing プロファイルと揃えている:
--   マスタ系の ID は VARCHAR、明細系は INTEGER GENERATED BY DEFAULT AS IDENTITY
--   日付は VARCHAR(100) (clouderby の型マッピングが TEXT のため)
--   IS_ACTIVE は VARCHAR(10) DEFAULT '1'
-- ============================================

-- ============================================
-- Branch / Organization (拠点・組織)
-- ============================================

-- 支店マスタ
CREATE TABLE BRN_BRANCHES (
    BRANCH_ID        VARCHAR(100) NOT NULL PRIMARY KEY,
    BRANCH_CODE      VARCHAR(100) NOT NULL UNIQUE,
    BRANCH_NAME      VARCHAR(500) NOT NULL,
    BRANCH_TYPE      VARCHAR(100) DEFAULT 'FULL_SERVICE',
    REGION           VARCHAR(200),
    ADDRESS          VARCHAR(1000),
    PHONE            VARCHAR(100),
    MANAGER_ID       VARCHAR(100),
    OPENED_DATE      VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 行員マスタ
CREATE TABLE BRN_EMPLOYEES (
    EMPLOYEE_ID      VARCHAR(100) NOT NULL PRIMARY KEY,
    BRANCH_ID        VARCHAR(100) NOT NULL,
    EMPLOYEE_NAME    VARCHAR(500) NOT NULL,
    EMPLOYEE_KANA    VARCHAR(500),
    ROLE             VARCHAR(100),
    EMAIL            VARCHAR(500),
    PHONE            VARCHAR(100),
    HIRED_DATE       VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (BRANCH_ID) REFERENCES BRN_BRANCHES(BRANCH_ID)
);

-- ATM マスタ
CREATE TABLE BRN_ATMS (
    ATM_ID           VARCHAR(100) NOT NULL PRIMARY KEY,
    BRANCH_ID        VARCHAR(100) NOT NULL,
    LOCATION_NAME    VARCHAR(500),
    ADDRESS          VARCHAR(1000),
    ATM_TYPE         VARCHAR(100) DEFAULT 'FULL_FUNCTION',
    CASH_BALANCE     DOUBLE DEFAULT 0,
    STATUS           VARCHAR(100) DEFAULT 'ONLINE',
    LAST_SERVICED_AT VARCHAR(100),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (BRANCH_ID) REFERENCES BRN_BRANCHES(BRANCH_ID)
);

-- ============================================
-- Customer Information File (顧客情報)
-- ============================================

-- 顧客マスタ
CREATE TABLE CIF_CUSTOMERS (
    CUSTOMER_ID      VARCHAR(100) NOT NULL PRIMARY KEY,
    CUSTOMER_NUMBER  VARCHAR(100) NOT NULL UNIQUE,
    CUSTOMER_NAME    VARCHAR(500) NOT NULL,
    CUSTOMER_KANA    VARCHAR(500),
    CUSTOMER_TYPE    VARCHAR(100) DEFAULT 'INDIVIDUAL',
    DATE_OF_BIRTH    VARCHAR(100),
    GENDER           VARCHAR(20),
    NATIONALITY      VARCHAR(100),
    OCCUPATION       VARCHAR(200),
    ANNUAL_INCOME    DOUBLE,
    EMAIL            VARCHAR(500),
    PHONE            VARCHAR(100),
    HOME_BRANCH_ID   VARCHAR(100),
    SEGMENT          VARCHAR(100) DEFAULT 'MASS',
    RISK_RATING      VARCHAR(50) DEFAULT 'LOW',
    ONBOARDED_DATE   VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (HOME_BRANCH_ID) REFERENCES BRN_BRANCHES(BRANCH_ID)
);

-- 顧客住所
CREATE TABLE CIF_ADDRESSES (
    ADDRESS_ID       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    ADDRESS_TYPE     VARCHAR(100) DEFAULT 'HOME',
    POSTAL_CODE      VARCHAR(50),
    PREFECTURE       VARCHAR(200),
    CITY             VARCHAR(200),
    STREET           VARCHAR(1000),
    VALID_FROM       VARCHAR(100),
    IS_PRIMARY       VARCHAR(10) DEFAULT '1',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID)
);

-- 本人確認 (KYC)
CREATE TABLE CIF_KYC_CHECKS (
    CHECK_ID         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    CHECK_TYPE       VARCHAR(100) NOT NULL,
    CHECK_DATE       VARCHAR(100) NOT NULL,
    DOCUMENT_TYPE    VARCHAR(100),
    DOCUMENT_NUMBER  VARCHAR(200),
    RESULT           VARCHAR(100) DEFAULT 'PASSED',
    EXPIRES_AT       VARCHAR(100),
    CHECKED_BY       VARCHAR(100),
    NOTES            VARCHAR(2000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID)
);

-- 顧客関係 (世帯・グループ)
CREATE TABLE CIF_RELATIONSHIPS (
    RELATIONSHIP_ID  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    RELATED_CUSTOMER_ID VARCHAR(100) NOT NULL,
    RELATIONSHIP_TYPE VARCHAR(100) NOT NULL,
    VALID_FROM       VARCHAR(100),
    NOTES            VARCHAR(2000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID),
    FOREIGN KEY (RELATED_CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID)
);

-- ============================================
-- Accounts (預金口座)
-- ============================================

-- 預金商品マスタ
CREATE TABLE ACC_PRODUCTS (
    PRODUCT_ID       VARCHAR(100) NOT NULL PRIMARY KEY,
    PRODUCT_CODE     VARCHAR(100) NOT NULL UNIQUE,
    PRODUCT_NAME     VARCHAR(500) NOT NULL,
    PRODUCT_TYPE     VARCHAR(100) NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    MIN_BALANCE      DOUBLE DEFAULT 0,
    MONTHLY_FEE      DOUBLE DEFAULT 0,
    BASE_RATE        DOUBLE DEFAULT 0,
    TERM_MONTHS      INTEGER,
    DESCRIPTION      VARCHAR(2000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 口座
CREATE TABLE ACC_ACCOUNTS (
    ACCOUNT_ID       VARCHAR(100) NOT NULL PRIMARY KEY,
    ACCOUNT_NUMBER   VARCHAR(100) NOT NULL UNIQUE,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    PRODUCT_ID       VARCHAR(100) NOT NULL,
    BRANCH_ID        VARCHAR(100) NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    BALANCE          DOUBLE DEFAULT 0,
    AVAILABLE_BALANCE DOUBLE DEFAULT 0,
    HOLD_AMOUNT      DOUBLE DEFAULT 0,
    OVERDRAFT_LIMIT  DOUBLE DEFAULT 0,
    OPENED_DATE      VARCHAR(100),
    CLOSED_DATE      VARCHAR(100),
    LAST_ACTIVITY_AT VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_ID) REFERENCES ACC_PRODUCTS(PRODUCT_ID),
    FOREIGN KEY (BRANCH_ID) REFERENCES BRN_BRANCHES(BRANCH_ID)
);

-- 日次残高
CREATE TABLE ACC_BALANCE_HISTORY (
    HISTORY_ID       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACCOUNT_ID       VARCHAR(100) NOT NULL,
    AS_OF_DATE       VARCHAR(100) NOT NULL,
    OPENING_BALANCE  DOUBLE DEFAULT 0,
    CLOSING_BALANCE  DOUBLE DEFAULT 0,
    DEBIT_TOTAL      DOUBLE DEFAULT 0,
    CREDIT_TOTAL     DOUBLE DEFAULT 0,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ACCOUNT_ID) REFERENCES ACC_ACCOUNTS(ACCOUNT_ID),
    CONSTRAINT UQ_ACC_BALANCE_DAY UNIQUE (ACCOUNT_ID, AS_OF_DATE)
);

-- 適用金利
CREATE TABLE ACC_INTEREST_RATES (
    RATE_ID          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    PRODUCT_ID       VARCHAR(100) NOT NULL,
    RATE_TYPE        VARCHAR(100) DEFAULT 'CREDIT',
    RATE             DOUBLE NOT NULL,
    EFFECTIVE_FROM   VARCHAR(100) NOT NULL,
    EFFECTIVE_TO     VARCHAR(100),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (PRODUCT_ID) REFERENCES ACC_PRODUCTS(PRODUCT_ID)
);

-- ============================================
-- Cards (カード) -- 取引が加盟店を参照するため先に定義
-- ============================================

-- 加盟店マスタ
CREATE TABLE CRD_MERCHANTS (
    MERCHANT_ID      VARCHAR(100) NOT NULL PRIMARY KEY,
    MERCHANT_NAME    VARCHAR(500) NOT NULL,
    MERCHANT_CATEGORY VARCHAR(200),
    MCC              VARCHAR(20),
    COUNTRY          VARCHAR(100) DEFAULT 'JP',
    CITY             VARCHAR(200),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- カード
CREATE TABLE CRD_CARDS (
    CARD_ID          VARCHAR(100) NOT NULL PRIMARY KEY,
    CARD_NUMBER_MASKED VARCHAR(100) NOT NULL,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    ACCOUNT_ID       VARCHAR(100) NOT NULL,
    CARD_TYPE        VARCHAR(100) DEFAULT 'DEBIT',
    BRAND            VARCHAR(100),
    CREDIT_LIMIT     DOUBLE DEFAULT 0,
    AVAILABLE_CREDIT DOUBLE DEFAULT 0,
    ISSUED_DATE      VARCHAR(100),
    EXPIRY_DATE      VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID),
    FOREIGN KEY (ACCOUNT_ID) REFERENCES ACC_ACCOUNTS(ACCOUNT_ID)
);

-- ============================================
-- Transactions (取引)
-- ============================================

-- 取引明細
CREATE TABLE TXN_TRANSACTIONS (
    TRANSACTION_ID   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    TRANSACTION_REF  VARCHAR(100) NOT NULL UNIQUE,
    ACCOUNT_ID       VARCHAR(100) NOT NULL,
    TRANSACTION_DATE VARCHAR(100) NOT NULL,
    VALUE_DATE       VARCHAR(100),
    TRANSACTION_TYPE VARCHAR(100) NOT NULL,
    CHANNEL          VARCHAR(100) DEFAULT 'ONLINE',
    AMOUNT           DOUBLE NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    BALANCE_AFTER    DOUBLE,
    DESCRIPTION      VARCHAR(1000),
    COUNTERPARTY_NAME VARCHAR(500),
    MERCHANT_ID      VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'POSTED',
    POSTED_BY        VARCHAR(100),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ACCOUNT_ID) REFERENCES ACC_ACCOUNTS(ACCOUNT_ID),
    FOREIGN KEY (MERCHANT_ID) REFERENCES CRD_MERCHANTS(MERCHANT_ID)
);

-- 振込
CREATE TABLE TXN_TRANSFERS (
    TRANSFER_ID      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    TRANSFER_REF     VARCHAR(100) NOT NULL UNIQUE,
    FROM_ACCOUNT_ID  VARCHAR(100) NOT NULL,
    TO_ACCOUNT_NUMBER VARCHAR(100),
    TO_BANK_CODE     VARCHAR(50),
    TO_BANK_NAME     VARCHAR(500),
    BENEFICIARY_NAME VARCHAR(500),
    AMOUNT           DOUBLE NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    FEE              DOUBLE DEFAULT 0,
    TRANSFER_DATE    VARCHAR(100) NOT NULL,
    SCHEDULED_DATE   VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'COMPLETED',
    FAILURE_REASON   VARCHAR(1000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (FROM_ACCOUNT_ID) REFERENCES ACC_ACCOUNTS(ACCOUNT_ID)
);

-- 自動振替 (口座振替・定期送金)
CREATE TABLE TXN_STANDING_ORDERS (
    ORDER_ID         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACCOUNT_ID       VARCHAR(100) NOT NULL,
    PAYEE_NAME       VARCHAR(500) NOT NULL,
    PAYEE_ACCOUNT    VARCHAR(100),
    AMOUNT           DOUBLE NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    FREQUENCY        VARCHAR(100) DEFAULT 'MONTHLY',
    NEXT_RUN_DATE    VARCHAR(100),
    START_DATE       VARCHAR(100),
    END_DATE         VARCHAR(100),
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ACCOUNT_ID) REFERENCES ACC_ACCOUNTS(ACCOUNT_ID)
);

-- カードオーソリ
CREATE TABLE CRD_AUTHORIZATIONS (
    AUTH_ID          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CARD_ID          VARCHAR(100) NOT NULL,
    MERCHANT_ID      VARCHAR(100) NOT NULL,
    AUTH_DATE        VARCHAR(100) NOT NULL,
    AMOUNT           DOUBLE NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    AUTH_CODE        VARCHAR(50),
    RESULT           VARCHAR(50) DEFAULT 'APPROVED',
    DECLINE_REASON   VARCHAR(500),
    IS_SETTLED       VARCHAR(10) DEFAULT '1',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CARD_ID) REFERENCES CRD_CARDS(CARD_ID),
    FOREIGN KEY (MERCHANT_ID) REFERENCES CRD_MERCHANTS(MERCHANT_ID)
);

-- ============================================
-- Lending (融資)
-- ============================================

-- 融資商品マスタ
CREATE TABLE LON_PRODUCTS (
    LOAN_PRODUCT_ID  VARCHAR(100) NOT NULL PRIMARY KEY,
    PRODUCT_CODE     VARCHAR(100) NOT NULL UNIQUE,
    PRODUCT_NAME     VARCHAR(500) NOT NULL,
    LOAN_TYPE        VARCHAR(100) NOT NULL,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    MIN_AMOUNT       DOUBLE,
    MAX_AMOUNT       DOUBLE,
    MIN_TERM_MONTHS  INTEGER,
    MAX_TERM_MONTHS  INTEGER,
    BASE_RATE        DOUBLE,
    DESCRIPTION      VARCHAR(2000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 融資契約
CREATE TABLE LON_LOANS (
    LOAN_ID          VARCHAR(100) NOT NULL PRIMARY KEY,
    LOAN_NUMBER      VARCHAR(100) NOT NULL UNIQUE,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    LOAN_PRODUCT_ID  VARCHAR(100) NOT NULL,
    BRANCH_ID        VARCHAR(100) NOT NULL,
    OFFICER_ID       VARCHAR(100),
    PRINCIPAL_AMOUNT DOUBLE NOT NULL,
    OUTSTANDING_BALANCE DOUBLE DEFAULT 0,
    INTEREST_RATE    DOUBLE NOT NULL,
    TERM_MONTHS      INTEGER NOT NULL,
    MONTHLY_PAYMENT  DOUBLE,
    DISBURSED_DATE   VARCHAR(100),
    MATURITY_DATE    VARCHAR(100),
    DELINQUENCY_DAYS INTEGER DEFAULT 0,
    STATUS           VARCHAR(100) DEFAULT 'ACTIVE',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UPDATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID),
    FOREIGN KEY (LOAN_PRODUCT_ID) REFERENCES LON_PRODUCTS(LOAN_PRODUCT_ID),
    FOREIGN KEY (BRANCH_ID) REFERENCES BRN_BRANCHES(BRANCH_ID),
    FOREIGN KEY (OFFICER_ID) REFERENCES BRN_EMPLOYEES(EMPLOYEE_ID)
);

-- 返済予定・実績
CREATE TABLE LON_REPAYMENTS (
    REPAYMENT_ID     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOAN_ID          VARCHAR(100) NOT NULL,
    INSTALLMENT_NO   INTEGER NOT NULL,
    DUE_DATE         VARCHAR(100) NOT NULL,
    PRINCIPAL_DUE    DOUBLE DEFAULT 0,
    INTEREST_DUE     DOUBLE DEFAULT 0,
    TOTAL_DUE        DOUBLE DEFAULT 0,
    PAID_DATE        VARCHAR(100),
    PAID_AMOUNT      DOUBLE,
    STATUS           VARCHAR(100) DEFAULT 'SCHEDULED',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (LOAN_ID) REFERENCES LON_LOANS(LOAN_ID),
    CONSTRAINT UQ_LON_REPAYMENT_INST UNIQUE (LOAN_ID, INSTALLMENT_NO)
);

-- 担保
CREATE TABLE LON_COLLATERALS (
    COLLATERAL_ID    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOAN_ID          VARCHAR(100) NOT NULL,
    COLLATERAL_TYPE  VARCHAR(100) NOT NULL,
    DESCRIPTION      VARCHAR(2000),
    APPRAISED_VALUE  DOUBLE,
    APPRAISAL_DATE   VARCHAR(100),
    LTV_RATIO        DOUBLE,
    STATUS           VARCHAR(100) DEFAULT 'PLEDGED',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (LOAN_ID) REFERENCES LON_LOANS(LOAN_ID)
);

-- ============================================
-- Risk (与信・リスク)
-- ============================================

-- 信用スコア
CREATE TABLE RSK_CREDIT_SCORES (
    SCORE_ID         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    SCORE_DATE       VARCHAR(100) NOT NULL,
    SCORE            INTEGER NOT NULL,
    SCORE_MODEL      VARCHAR(100),
    RATING           VARCHAR(50),
    PD_PERCENT       DOUBLE,
    SOURCE           VARCHAR(200),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID)
);

-- 与信残高 (エクスポージャ)
CREATE TABLE RSK_EXPOSURES (
    EXPOSURE_ID      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    AS_OF_DATE       VARCHAR(100) NOT NULL,
    EXPOSURE_TYPE    VARCHAR(100) NOT NULL,
    EXPOSURE_AMOUNT  DOUBLE DEFAULT 0,
    LIMIT_AMOUNT     DOUBLE DEFAULT 0,
    UTILIZATION_PCT  DOUBLE,
    CURRENCY         VARCHAR(10) DEFAULT 'JPY',
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID)
);

-- ============================================
-- AML / Compliance (マネロン対策・コンプライアンス)
-- ============================================

-- 不審取引アラート
CREATE TABLE AML_ALERTS (
    ALERT_ID         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ALERT_NUMBER     VARCHAR(100) NOT NULL UNIQUE,
    CUSTOMER_ID      VARCHAR(100) NOT NULL,
    TRANSACTION_ID   INTEGER,
    ALERT_DATE       VARCHAR(100) NOT NULL,
    RULE_CODE        VARCHAR(100) NOT NULL,
    RULE_NAME        VARCHAR(500),
    SEVERITY         VARCHAR(50) DEFAULT 'MEDIUM',
    STATUS           VARCHAR(100) DEFAULT 'OPEN',
    ASSIGNED_TO      VARCHAR(100),
    RESOLUTION       VARCHAR(2000),
    CLOSED_DATE      VARCHAR(100),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (CUSTOMER_ID) REFERENCES CIF_CUSTOMERS(CUSTOMER_ID),
    FOREIGN KEY (TRANSACTION_ID) REFERENCES TXN_TRANSACTIONS(TRANSACTION_ID)
);

-- 制裁・要注意リスト
CREATE TABLE AML_WATCHLIST (
    WATCHLIST_ID     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LIST_NAME        VARCHAR(200) NOT NULL,
    ENTITY_NAME      VARCHAR(500) NOT NULL,
    ENTITY_TYPE      VARCHAR(100) DEFAULT 'INDIVIDUAL',
    COUNTRY          VARCHAR(100),
    LISTED_DATE      VARCHAR(100),
    REFERENCE        VARCHAR(500),
    NOTES            VARCHAR(2000),
    IS_ACTIVE        VARCHAR(10) DEFAULT '1',
    CREATED_AT       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- ============================================
-- Additional Indexes
-- ============================================
CREATE INDEX IDX_CIF_CUSTOMERS_TYPE ON CIF_CUSTOMERS(CUSTOMER_TYPE);
CREATE INDEX IDX_CIF_CUSTOMERS_SEGMENT ON CIF_CUSTOMERS(SEGMENT);
CREATE INDEX IDX_CIF_CUSTOMERS_BRANCH ON CIF_CUSTOMERS(HOME_BRANCH_ID);
CREATE INDEX IDX_ACC_ACCOUNTS_CUST ON ACC_ACCOUNTS(CUSTOMER_ID);
CREATE INDEX IDX_ACC_ACCOUNTS_STATUS ON ACC_ACCOUNTS(STATUS);
CREATE INDEX IDX_TXN_TRANSACTIONS_ACC ON TXN_TRANSACTIONS(ACCOUNT_ID);
CREATE INDEX IDX_TXN_TRANSACTIONS_DATE ON TXN_TRANSACTIONS(TRANSACTION_DATE);
CREATE INDEX IDX_TXN_TRANSACTIONS_TYPE ON TXN_TRANSACTIONS(TRANSACTION_TYPE);
CREATE INDEX IDX_CRD_AUTH_CARD ON CRD_AUTHORIZATIONS(CARD_ID);
CREATE INDEX IDX_LON_LOANS_CUST ON LON_LOANS(CUSTOMER_ID);
CREATE INDEX IDX_LON_LOANS_STATUS ON LON_LOANS(STATUS);
CREATE INDEX IDX_LON_REPAYMENTS_LOAN ON LON_REPAYMENTS(LOAN_ID);
CREATE INDEX IDX_AML_ALERTS_STATUS ON AML_ALERTS(STATUS);
